#!/usr/bin/env python3
import sys, math, fractions, itertools


def solve(N: int, a: "List[int]", b: "List[int]", c: "List[int]", d: "List[int]"):
    R = list(reversed(sorted(zip(a, b), key=lambda x: x[1])))
    B = sorted(zip(c, d), key=lambda x: x[0])
    P = [0] * N
    counter = 0
    for b in B:
        for i, (a, p) in enumerate(zip(R, P)):
            if p == 0 and a[0] < b[0] and a[1] < b[1]:
                P[i] = 1
                counter += 1
                break
    print(counter)
    return


# Generated by 1.1.4 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    a = [int()] * (N)  # type: "List[int]" 
    b = [int()] * (N)  # type: "List[int]" 
    for i in range(N):
        a[i] = int(next(tokens))
        b[i] = int(next(tokens))
    c = [int()] * (N)  # type: "List[int]" 
    d = [int()] * (N)  # type: "List[int]" 
    for i in range(N):
        c[i] = int(next(tokens))
        d[i] = int(next(tokens))
    solve(N, a, b, c, d)

if __name__ == '__main__':
    main()
